-- A claim bound by its person's last statement: stated is true while bound, and stated_due is the figure it
-- was bound to (null when its grade had no rate then). A statement rebinds every claim of the person.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);
-- The statements taken of a person: their due-total then (null when n/a) and the sheet's today then.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet     VARCHAR(200)   NOT NULL,
    person    BIGINT         NOT NULL REFERENCES person (id),
    due_total DECIMAL(15, 2),
    taken_on  DATE           NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet, person, id);
-- A statement now binds a claim's due as shown, late charge (and floor) included: stated_due is that due, and
-- while bound the claim shows it, its late charge no longer following the sheet's today.
COMMENT ON COLUMN claim.stated_due IS 'The due a statement bound, as shown then (late charge included); null when n/a';
-- The order of a person's statements: the one with the highest seq is their last. A statement taken is placed after
-- the person's others; statements that move with a merge or transfer onto a person who has their own are placed
-- before them, so the receiving person's last statement stays theirs.
ALTER TABLE statement ADD COLUMN seq BIGINT;
UPDATE statement SET seq = id;
ALTER TABLE statement ALTER COLUMN seq SET NOT NULL;
-- A statement may be taken as of a date on or before the sheet's today: as_of is that date (null when it was taken
-- now), shown as the statement's date in place of taken_on.
ALTER TABLE statement ADD COLUMN as_of DATE;
-- The sheet as it stood when its today moved from from_today to to_today: every change made while the sheet's today
-- was from_today counts in it, and none made after. The state is the people, claims, rates and settings then (JSON).
CREATE TABLE sheet_state (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet      VARCHAR(200) NOT NULL,
    from_today DATE         NOT NULL,
    to_today   DATE         NOT NULL,
    state      CLOB         NOT NULL
);
CREATE INDEX sheet_state_sheet ON sheet_state (sheet, id);

