import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { useIsLatest } from '../../query/useIsLatest';
import { byUser } from '../session/session';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { useShown } from '../columns/columns';
import { peoplePath, personActionKey } from '../people/people';
import type { Person } from '../people/people';
import { claimsKey } from '../claims/claims';
import { statementsKey, useStatements } from './statements';
import type { StatementSummary } from './statements';
import { Fig } from '../locale/Fig';

function StatementHeader({ sheet, user }: { sheet: string; user: string }) {
  const shown = useShown(sheet, user);
  return (
    <>
      {shown('statement-count') && <th>Statements</th>}
      {shown('stated-total') && <th>Stated total</th>}
      {shown('statement-date') && <th>Stated on</th>}
      <th>Statement lines</th>
      <th />
    </>
  );
}

// A person's statements: how many, the last one's due-total and date, a line per statement (oldest first), the button that takes the next and the one
// that cancels the last. Taking one binds their counting claims to their figures now, and cancelling one makes the
// claims it bound live again, so the claims are re-read before the count moves on. A date beside the button takes
// the statement as of that date (blank: now); it is cleared once the statement is taken or refused, so a refused date
// never carries into the next press, and changing it clears the statement's error.
function PersonStatements({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
  const shown = useShown(sheet, user);
  const queryClient = useQueryClient();
  const { data: all = [] } = useStatements(sheet);
  const mine = all.find((s) => s.person === person.id);
  const [asof, setAsof] = useState('');
  const take = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: (date: string) =>
      postJson<StatementSummary[]>(byUser(`${peoplePath(sheet)}/${person.id}/statement`, user), { asof: date }),
    onSuccess: async (updated) => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
      queryClient.setQueryData(statementsKey(sheet), updated);
    },
    onSettled: () => setAsof(''),
  });
  const cancel = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: () =>
      postJson<StatementSummary[]>(byUser(`${peoplePath(sheet)}/${person.id}/unstate`, user), {}),
    onSuccess: async (updated) => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
      queryClient.setQueryData(statementsKey(sheet), updated);
    },
  });
  const act = useSubmitOnce(take);
  const actCancel = useSubmitOnce(cancel);
  const latest = useIsLatest(personActionKey(sheet, person.id), take.submittedAt);
  const latestCancel = useIsLatest(personActionKey(sheet, person.id), cancel.submittedAt);

  return (
    <>
      {shown('statement-count') && <td data-testid="person-statement-count">{mine?.count ?? 0}</td>}
      {shown('stated-total') && <td data-testid="person-stated-total"><Fig>{mine?.lastDueTotal ?? ''}</Fig></td>}
      {shown('statement-date') && <td data-testid="person-statement-date">{mine?.lastDate ?? ''}</td>}
      <td data-testid="person-statement-lines">
        {(mine?.lines ?? []).map((line, i) => (
          <div key={i} data-testid="person-statement-line-line">
            {line.date} <Fig>{line.dueTotal}</Fig>
          </div>
        ))}
      </td>
      <td>
        <input
          type="date"
          data-testid="person-statement-asof"
          aria-label="Statement as of"
          value={asof}
          onChange={(e) => {
            setAsof(e.target.value);
            take.reset();
          }}
        />{' '}
        <button type="button" data-testid="person-statement" disabled={take.isPending} onClick={() => act(asof)}>
          Statement
        </button>{' '}
        <button type="button" data-testid="person-unstate" disabled={cancel.isPending} onClick={() => actCancel()}>
          Cancel statement
        </button>
        {take.isError && latest && (
          <span data-testid="person-error" role="alert">
            {' '}The statement could not be taken.
          </span>
        )}
        {cancel.isError && latestCancel && !(take.isError && latest) && (
          <span data-testid="person-error" role="alert">
            {' '}The statement could not be cancelled.
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 20, Component: StatementHeader }),
  PersonColumns.fill({ order: 20, Component: PersonStatements }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person's statements: how many were taken, and the last one's due-total (two decimals, or n/a) and date
 *  (yyyy-MM-dd, the sheet's today when it was taken), and a line per statement standing (its date and due-total), oldest
 *  first by date. A person with none is absent. */
export type StatementSummary = { person: number; count: number; lastDueTotal: string; lastDate: string; lines: StatementLine[] };

/** One statement standing: its date (yyyy-MM-dd) and due-total (two decimals, or n/a). */
export type StatementLine = { date: string; dueTotal: string };

export const statementsKey = (sheet: string) => ['statements', sheet] as const;

export const statementsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/statements`;

/** The statements taken on the sheet, per person. */
export function useStatements(sheet: string) {
  return useQuery({
    queryKey: statementsKey(sheet),
    queryFn: () => getJson<StatementSummary[]>(statementsPath(sheet)),
  });
}

